reference_solution:
def power_range_products(n,queries):
    powers=[];bit=1
    while bit<=n:
        if n&bit:powers.append(bit)
        bit<<=1
    mod=10**9+7;answer=[]
    for left,right in queries:
        product=1
        for index in range(left,right+1):product=product*powers[index]%mod
        answer.append(product)
    return answer

